INSERT INTO `announcements` VALUES (5,'Food Handling and Sanitation Seminar','On July 7, 2026, at 8:00 A.M., the Barangay Government of Barangay Natumolan, through the initiative of the Barangay Sanitary Inspector and the Natumolan Barangay Council, in collaboration with the Rural Health Unit (Sanitation Office) Tagoloan, Misamis Oriental and the Business Licensing Office, successfully conducted a Food Handling and Sanitation Seminar for food establishment owners, managers, food handlers, vendors, and other personnel involved in food preparation and food service within the barangay.\r\nThe seminar aimed to strengthen awareness and compliance with proper food safety, sanitation, and hygiene practices to help prevent food-borne illnesses and promote the health and well-being of the community.\r\nThe Barangay Government extends its sincere appreciation to all participants and partner agencies for their active participation and continued commitment to ensuring safe, clean, and sanitary food service in Barangay Natumolan.',NULL,'On July 7, 2026, at 8:00 A.M., the Barangay Government of Barangay Natumolan, through the initiative of the Barangay Sanitary Inspector and the Natumolan Barangay Council, in collaboration with the Ru','Published','Event','Barangay Natumolan Court','2026-07-07 00:00:00','news/l2cR2zVZfjjOwWORDKxoodOQ6ws580QZiAON7IP9.jpg',0,'8:00 AM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-20 14:20:53',14,'2026-07-20 06:20:53','2026-09-05 03:13:53'),(8,'MONTHLY ROAD CLEARING ACTIVITY','In line with the Barangay\'s commitment to maintaining a clean, orderly, and safe community, Barangay Natumolan successfully conducted its Monthly Road Clearing Activity on July 13, 2026, under the leadership of Punong Barangay Paing Vidal, together with the members of the Sangguniang Barangay, Barangay Tanods, BDRR, and other Barangay Personnel.\r\nThe activity aimed to clear public roads and sidewalks of obstructions, ensuring safer and more convenient passage for motorists and pedestrians while promoting discipline, cleanliness, and public safety throughout the barangay.\r\nTogether, let us continue working hand in hand for a cleaner, safer, and more progressive Barangay Natumolan.\r\n#RoadClearing2026 #BarangayNatumolan #CommunityService #CleanAndSafeCommunity #WorkingTogether',NULL,'In line with the Barangay\'s commitment to maintaining a clean, orderly, and safe community, Barangay Natumolan successfully conducted its Monthly Road Clearing Activity on July 13, 2026, under the lea','Published','Event','NATUMOLAN, TAGOLOAN, MISAMIS ORIENTAL','2026-07-13 00:00:00','news/PU7c0jqJmQoRyDwyBbvI9dPLU4NTSOnuPKmXHGBH.jpg',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-21 00:19:56',14,'2026-07-20 16:19:56','2026-09-05 03:13:53');
/*!40000 ALTER TABLE `announcements` ENABLE KEYS */;
