DROP TABLE IF EXISTS `child_health`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `child_health` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `child_id` bigint(20) unsigned NOT NULL,
  `birth_date` date NOT NULL,
  `birth_weight` decimal(5,2) DEFAULT NULL,
  `fully_immunized_status` int(11) NOT NULL DEFAULT 0,
  `current_weight` decimal(5,2) DEFAULT NULL,
  `current_height` decimal(5,2) DEFAULT NULL,
  `nutritional_status` varchar(255) DEFAULT NULL,
  `growth_monitoring_notes` text DEFAULT NULL,
  `vitamin_services_received` tinyint(1) NOT NULL DEFAULT 0,
  `breastfeeding_status` text DEFAULT NULL,
  `feeding_counseling_notes` text DEFAULT NULL,
  `referral_needed` tinyint(1) NOT NULL DEFAULT 0,
  `referral_destination` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `child_health_child_id_foreign` (`child_id`),
  CONSTRAINT `child_health_child_id_foreign` FOREIGN KEY (`child_id`) REFERENCES `residents` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
