  KEY `health_visits_service_provider_id_foreign` (`service_provider_id`),
  CONSTRAINT `health_visits_patient_id_foreign` FOREIGN KEY (`patient_id`) REFERENCES `residents` (`id`) ON DELETE CASCADE,
  CONSTRAINT `health_visits_service_provider_id_foreign` FOREIGN KEY (`service_provider_id`) REFERENCES `users` (`id`)
