  `q7_nationality_other` varchar(100) DEFAULT NULL,
  `q8_marital_status` tinyint(3) unsigned DEFAULT NULL,
  `q9_religion` varchar(100) DEFAULT NULL,
  `q10_ethnicity` varchar(100) DEFAULT NULL,
  `q11_education` tinyint(3) unsigned DEFAULT NULL,
  `q12_enrolled` tinyint(3) unsigned DEFAULT NULL,
  `q13_school_level` tinyint(3) unsigned DEFAULT NULL,
  `q14_school_place` varchar(150) DEFAULT NULL,
  `q15_monthly_income` decimal(14,2) unsigned DEFAULT NULL,
  `q16_income_source` tinyint(3) unsigned DEFAULT NULL,
  `q17_work_status` tinyint(3) unsigned DEFAULT NULL,
  `q18_work_place` varchar(150) DEFAULT NULL,
  `q19_delivery_place` tinyint(3) unsigned DEFAULT NULL,
  `q19_other` varchar(100) DEFAULT NULL,
  `q20_birth_attendant` tinyint(3) unsigned DEFAULT NULL,
  `q20_other` varchar(100) DEFAULT NULL,
  `q21_immunization` varchar(120) DEFAULT NULL,
  `q22_pregnancies` tinyint(3) unsigned DEFAULT NULL,
  `q22_living_children` tinyint(3) unsigned DEFAULT NULL,
  `q23_fp_method` tinyint(3) unsigned DEFAULT NULL,
  `q24_fp_source` tinyint(3) unsigned DEFAULT NULL,
  `q24_other` varchar(100) DEFAULT NULL,
  `q25_fp_intention` tinyint(3) unsigned DEFAULT NULL,
  `q25_detail` varchar(150) DEFAULT NULL,
  `q26_health_insurance` tinyint(3) unsigned DEFAULT NULL,
  `q26_other` varchar(100) DEFAULT NULL,
  `q27_facility_visited` tinyint(3) unsigned DEFAULT NULL,
  `q27_other` varchar(100) DEFAULT NULL,
  `q28_visit_reason` tinyint(3) unsigned DEFAULT NULL,
  `q28_other` varchar(100) DEFAULT NULL,
  `q29_disability` tinyint(3) unsigned DEFAULT NULL,
  `q30_solo_parent` tinyint(3) unsigned DEFAULT NULL,
  `q31_senior_registered` tinyint(3) unsigned DEFAULT NULL,
  `q32_voter_barangay` varchar(100) DEFAULT NULL,
  `q33_residence_5yrs` varchar(150) DEFAULT NULL,
  `q34_residence_6mos` varchar(150) DEFAULT NULL,
  `q35_stay_years` smallint(5) unsigned DEFAULT NULL,
  `q35_stay_months` tinyint(3) unsigned DEFAULT NULL,
  `q36_resident_type` tinyint(3) unsigned DEFAULT NULL,
  `q37_transfer_month` tinyint(3) unsigned DEFAULT NULL,
  `q37_transfer_year` smallint(5) unsigned DEFAULT NULL,
  `q38a_leave_reason` tinyint(3) unsigned DEFAULT NULL,
  `q38b_leave_reason` tinyint(3) unsigned DEFAULT NULL,
  `q38c_leave_reason` tinyint(3) unsigned DEFAULT NULL,
  `q38_other` varchar(120) DEFAULT NULL,
  `q39_will_return` tinyint(3) unsigned DEFAULT NULL,
  `q39_when` varchar(60) DEFAULT NULL,
  `q40a_transfer_reason` tinyint(3) unsigned DEFAULT NULL,
  `q40b_transfer_reason` tinyint(3) unsigned DEFAULT NULL,
  `q40c_transfer_reason` tinyint(3) unsigned DEFAULT NULL,
  `q40_other` varchar(120) DEFAULT NULL,
  `q41_intends_to_stay` tinyint(3) unsigned DEFAULT NULL,
