  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rbim_census_members_rbim_census_id_line_no_unique` (`rbim_census_id`,`line_no`),
  KEY `rbim_census_members_resident_id_foreign` (`resident_id`),
