--
-- Table structure for table `rbim_censuses`
--

DROP TABLE IF EXISTS `rbim_censuses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `rbim_censuses` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `census_no` varchar(20) DEFAULT NULL,
  `is_institutional` tinyint(1) NOT NULL DEFAULT 0,
  `province` varchar(100) DEFAULT NULL,
  `city_municipality` varchar(100) DEFAULT NULL,
  `barangay` varchar(100) DEFAULT NULL,
  `zone_purok` varchar(100) DEFAULT NULL,
  `address_unit` varchar(150) DEFAULT NULL,
  `address_house_lot` varchar(150) DEFAULT NULL,
  `address_street` varchar(150) DEFAULT NULL,
  `respondent_name` varchar(150) DEFAULT NULL,
  `household_head_name` varchar(150) DEFAULT NULL,
  `total_members` smallint(5) unsigned DEFAULT NULL,
  `household_id` bigint(20) unsigned DEFAULT NULL,
  `q45_housing_tenure` tinyint(3) unsigned DEFAULT NULL,
  `q46_lot_tenure` tinyint(3) unsigned DEFAULT NULL,
  `q47_lighting_fuel` tinyint(3) unsigned DEFAULT NULL,
  `q47_other` varchar(100) DEFAULT NULL,
  `q48_cooking_fuel` tinyint(3) unsigned DEFAULT NULL,
  `q48_other` varchar(100) DEFAULT NULL,
  `q49_water_source` tinyint(3) unsigned DEFAULT NULL,
  `q49_other` varchar(100) DEFAULT NULL,
  `q50a_garbage_disposal` tinyint(3) unsigned DEFAULT NULL,
  `q50b_segregates` tinyint(3) unsigned DEFAULT NULL,
  `q51_toilet` tinyint(3) unsigned DEFAULT NULL,
  `q51_other` varchar(100) DEFAULT NULL,
  `q52_building_type` tinyint(3) unsigned DEFAULT NULL,
  `q53_outer_wall` tinyint(3) unsigned DEFAULT NULL,
  `q53_other` varchar(100) DEFAULT NULL,
