DROP TABLE IF EXISTS `resident_sectors`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `resident_sectors` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `resident_id` bigint(20) unsigned NOT NULL,
  `sector_type` varchar(255) NOT NULL,
  `reference_no` varchar(60) DEFAULT NULL,
  `issued_on` date DEFAULT NULL,
  `valid_until` date DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  `enrolled_date` date DEFAULT NULL,
  `unenrolled_date` date DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `resident_sectors_resident_id_sector_type_unique` (`resident_id`,`sector_type`),
  CONSTRAINT `resident_sectors_resident_id_foreign` FOREIGN KEY (`resident_id`) REFERENCES `residents` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=930 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

