--
-- Table structure for table `residents`
--

DROP TABLE IF EXISTS `residents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `residents` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `resident_number` varchar(255) NOT NULL,
  `record_type` varchar(20) NOT NULL DEFAULT 'Resident',
  `first_name` varchar(255) NOT NULL,
  `middle_name` varchar(255) DEFAULT NULL,
  `mother_maiden_name` varchar(255) DEFAULT NULL,
  `last_name` varchar(255) NOT NULL,
  `suffix` varchar(255) DEFAULT NULL,
  `gender` enum('Male','Female','Other') DEFAULT NULL,
  `birthdate` date DEFAULT NULL,
  `birthdate_is_estimated` tinyint(1) NOT NULL DEFAULT 0,
  `birth_place` varchar(255) DEFAULT NULL,
  `civil_status` varchar(255) DEFAULT NULL,
  `spouse_id` bigint(20) unsigned DEFAULT NULL,
  `occupation` varchar(255) DEFAULT NULL,
  `contact_number` varchar(255) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `household_id` bigint(20) unsigned DEFAULT NULL,
  `residency_status` enum('Permanent','Temporary','Migrant') NOT NULL DEFAULT 'Permanent',
  `length_of_residence_years` int(11) DEFAULT NULL,
  `zone_purok` varchar(255) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `educational_attainment` varchar(255) DEFAULT NULL,
  `demographic_classification` enum('Senior Citizen','PWD','Solo Parent','Youth','Child','Adult','Others') DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `life_status` varchar(20) NOT NULL DEFAULT 'Alive',
  `date_of_death` date DEFAULT NULL,
  `life_status_note` varchar(255) DEFAULT NULL,
  `merged_into_id` bigint(20) unsigned DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `residents_resident_number_unique` (`resident_number`),
