INSERT INTO `service_guides` VALUES (1,'Main Office','Barangay Clearance','General clearance certifying no derogatory record in the barangay.','Valid ID, proof of residency','₱50.00','Mon–Fri, 8AM–5PM','clearance,police,employment,requirement',1,'2026-07-19 19:16:15','2026-07-19 19:16:15'),(2,'Main Office','Certificate of Residency','Proof that you are a bona fide resident of Barangay Natumolan.','Valid ID','₱30.00','Mon–Fri, 8AM–5PM','residency,proof,address',1,'2026-07-19 19:16:15','2026-07-19 19:16:15'),(3,'Main Office','Certificate of Indigency','For qualified low-income residents; used for medical, educational, and legal assistance.','Valid ID, interview','Free','Mon–Fri, 8AM–5PM','indigency,indigent,assistance,medical,scholarship,free',1,'2026-07-19 19:16:15','2026-07-19 19:16:15'),(4,'Main Office','First-Time Jobseeker Certification','Fee exemption certificate under RA 11261 for first-time jobseekers.','Valid ID, oath','Free','Mon–Fri, 8AM–5PM','jobseeker,first time,job,work,ra 11261',1,'2026-07-19 19:16:15','2026-07-19 19:16:15'),(5,'Main Office','Business Barangay Clearance','Required for new and renewing businesses in the barangay.','DTI/SEC registration, lease or land title, valid ID','₱200.00','Mon–Fri, 8AM–5PM','business,permit,store,sari-sari,enterprise',1,'2026-07-19 19:16:15','2026-07-19 19:16:15'),(6,'Main Office','Blotter Report','Official recording of incidents for documentation and resolution.','Valid ID, incident details','Free','Daily, 24/7 on-duty tanod','blotter,incident,report,complaint',1,'2026-07-19 19:16:15','2026-07-19 19:16:15'),(7,'Lupon','Katarungang Pambarangay (Dispute Settlement)','Community mediation and conciliation of disputes between residents.','Complaint statement, valid ID','Filing fee ₱20.00','Mon–Fri, 8AM–5PM','dispute,away,mediation,settlement,complaint,neighbor,utang,debt',1,'2026-07-19 19:16:15','2026-07-19 19:16:15'),(8,'VAWC','VAWC Assistance','Confidential assistance and protection for women and children. Walk in any time — you will be assisted immediately and privately.','None — immediate assistance','Free','Daily, 24/7 hotline','vawc,violence,abuse,women,children,protection,bpo,help',1,'2026-07-19 19:16:15','2026-07-19 19:16:15'),(9,'Health Station','Medical Consultation','Free basic consultation, vital signs, and health advice.','Barangay health record (or register on site)','Free','Mon–Fri, 8AM–4PM','checkup,consultation,sick,medicine,bp,sugar',1,'2026-07-19 19:16:15','2026-07-19 19:16:15'),(10,'Health Station','Child Immunization','Routine childhood vaccines per DOH schedule.','Child\'s immunization card','Free','Wed, 8AM–12NN','vaccine,bakuna,immunization,child,baby',1,'2026-07-19 19:16:15','2026-07-19 19:16:15'),(11,'Health Station','Prenatal Care','Pregnancy registration, prenatal check-ups, and maternal counseling.','Valid ID','Free','Tue & Thu, 8AM–12NN','buntis,pregnant,prenatal,mother,delivery',1,'2026-07-19 19:16:15','2026-07-19 19:16:15'),(12,'Population','Resident Registration & Portal Account','Register as a resident and request an online portal account (created by the Population Office after verification).','Valid ID, proof of residency','Free','Mon–Fri, 8AM–5PM','register,account,portal,online,login,sign up',1,'2026-07-19 19:16:15','2026-07-19 19:16:15');
