CREATE TABLE `users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `role` enum('Punong Barangay','Secretary','Clerk','VAWC Officer','Lupon Secretary','Population Worker','Health Personnel','SK Chairperson','SK Kagawad','SK Secretary','Admin','Resident') NOT NULL DEFAULT 'Clerk',
  `office` enum('Main Office','VAWC','Lupon','Population','Health Station','SK','Admin','Resident') NOT NULL DEFAULT 'Main Office',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `activated_at` datetime DEFAULT NULL,
  `otp_code` varchar(255) DEFAULT NULL,
  `otp_expires_at` datetime DEFAULT NULL,
  `otp_sent_at` datetime DEFAULT NULL,
  `otp_attempts` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `resident_id` bigint(20) unsigned DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `password_set_at` datetime DEFAULT NULL,
  `password_set_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`),
  UNIQUE KEY `users_resident_id_unique` (`resident_id`),
  KEY `users_created_by_foreign` (`created_by`),
  KEY `users_password_set_by_foreign` (`password_set_by`),
  CONSTRAINT `users_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_password_set_by_foreign` FOREIGN KEY (`password_set_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_resident_id_foreign` FOREIGN KEY (`resident_id`) REFERENCES `residents` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=324 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
