--
-- Table structure for table `vawc_access_logs`
--

DROP TABLE IF EXISTS `vawc_access_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `vawc_access_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `vawc_case_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `action` varchar(255) NOT NULL,
  `detail` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vawc_access_logs_user_id_foreign` (`user_id`),
  KEY `vawc_access_logs_vawc_case_id_created_at_index` (`vawc_case_id`,`created_at`),
  CONSTRAINT `vawc_access_logs_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `vawc_access_logs_vawc_case_id_foreign` FOREIGN KEY (`vawc_case_id`) REFERENCES `vawc_cases` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=380 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

